    "arrays", "Private rbtRow As Long\nPrivate rbtOk As Boolean\nSub Main()\n    Dim a(1 To 3) As Long\n    a(1) = 10: a(2) = 20: a(3) = 30\n    On Error Resume Next: rbtOk = False: P \"lbound\", LBound(a): If Not rbtOk Then PE \"lbound\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"ubound\", UBound(a): If Not rbtOk Then PE \"ubound\", Err.Number: Err.Clear\n    Dim b() As String\n    ReDim b(2)\n    b(0) = \"x\": b(2) = \"z\"\n    ReDim Preserve b(4)\n    On Error Resume Next: rbtOk = False: P \"preserve\", b(2) & \"|\" & b(4) & \"|\" & UBound(b): If Not rbtOk Then PE \"preserve\", Err.Number: Err.Clear\n    Dim m(1 To 2, 1 To 3)\n    m(2, 3) = 7\n    On Error Resume Next: rbtOk = False: P \"2d ubound dim 2\", UBound(m, 2): If Not rbtOk Then PE \"2d ubound dim 2\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"2d value\", m(2, 3): If Not rbtOk Then PE \"2d value\", Err.Number: Err.Clear\n    Dim v\n    v = Array(1, \"two\", 3.5)\n    On Error Resume Next: rbtOk = False: P \"array typename\", TypeName(v): If Not rbtOk Then PE \"array typename\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"array item\", v(1): If Not rbtOk Then PE \"array item\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"isarray\", IsArray(v): If Not rbtOk Then PE \"isarray\", Err.Number: Err.Clear\n    Erase a\n    On Error Resume Next: rbtOk = False: P \"erase fixed\", a(2): If Not rbtOk Then PE \"erase fixed\", Err.Number: Err.Clear\n    Dim s\n    s = Split(\"p q r\")\n    On Error Resume Next: rbtOk = False: P \"split default\", s(2): If Not rbtOk Then PE \"split default\", Err.Number: Err.Clear\n    Double3 a\n    On Error Resume Next: rbtOk = False: P \"byref array\", a(1): If Not rbtOk Then PE \"byref array\", Err.Number: Err.Clear\n    Dim e()\n    On Error Resume Next: rbtOk = False: P \"empty dynamic ubound\", \"unset\": If Not rbtOk Then PE \"empty dynamic ubound\", Err.Number: Err.Clear\n    On Error Resume Next\n    On Error Resume Next: rbtOk = False: P \"ubound unallocated\", UBound(e): If Not rbtOk Then PE \"ubound unallocated\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"ubound unallocated err\", Err.Number: If Not rbtOk Then PE \"ubound unallocated err\", Err.Number: Err.Clear\n    Err.Clear\n    On Error Resume Next: rbtOk = False: P \"out of range\", a(9): If Not rbtOk Then PE \"out of range\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"out of range err\", Err.Number: If Not rbtOk Then PE \"out of range err\", Err.Number: Err.Clear\nEnd Sub\nSub Double3(arr)\n    arr(1) = 99\nEnd Sub\n\nSub P(label, v)\n    rbtOk = True\n    rbtRow = rbtRow + 1\n    Worksheets(1).Cells(rbtRow, 1).Value = label\n    Worksheets(1).Cells(rbtRow, 3).Value = TypeName(v)\n    If IsObject(v) Or IsArray(v) Then Exit Sub\n    On Error Resume Next\n    Worksheets(1).Cells(rbtRow, 2).Value = v\n    If Err.Number <> 0 Then Worksheets(1).Cells(rbtRow, 2).Value = \"#cell \" & Err.Number: Err.Clear\n    Worksheets(1).Cells(rbtRow, 4).Value = \"'\" & CStr(v)\n    If Err.Number <> 0 Then Worksheets(1).Cells(rbtRow, 4).Value = \"#CStr \" & Err.Number\nEnd Sub\nSub PE(label, number)\n    rbtRow = rbtRow + 1\n    Worksheets(1).Cells(rbtRow, 1).Value = label\n    Worksheets(1).Cells(rbtRow, 2).Value = \"#ERR \" & number\nEnd Sub\n\n\nSub RbtParityMain()\n    On Error GoTo failed\n    Main\n    Exit Sub\nfailed:\n    Worksheets(1).Range(\"Z1\").Value = \"#ERR \" & Err.Number & \" \" & Err.Description\nEnd Sub\n"
    "classes-like", "Private rbtRow As Long\nPrivate rbtOk As Boolean\nType Point\n    X As Double\n    Y As Double\nEnd Type\nEnum Colour\n    Red = 1\n    Green\n    Blue = 10\nEnd Enum\nPrivate counter As Long\nSub Main()\n    Dim pt As Point, q As Point\n    pt.X = 3: pt.Y = 4\n    q = pt\n    q.X = 100\n    On Error Resume Next: rbtOk = False: P \"udt copy\", pt.X & \",\" & q.X: If Not rbtOk Then PE \"udt copy\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"udt calc\", Dist(pt): If Not rbtOk Then PE \"udt calc\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"enum\", Green + Blue: If Not rbtOk Then PE \"enum\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"static\", Bump() & Bump() & Bump(): If Not rbtOk Then PE \"static\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"module var\", counter: If Not rbtOk Then PE \"module var\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"optional default\", Opt(1): If Not rbtOk Then PE \"optional default\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"optional given\", Opt(1, 5): If Not rbtOk Then PE \"optional given\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"ismissing\", Missing(): If Not rbtOk Then PE \"ismissing\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"paramarray\", Total(1, 2, 3, 4): If Not rbtOk Then PE \"paramarray\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"named args\", Opt(b:=7, a:=1): If Not rbtOk Then PE \"named args\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"byval\", ByValTest(): If Not rbtOk Then PE \"byval\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"recursion\", Fact(10): If Not rbtOk Then PE \"recursion\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"function as array\", Squares()(3): If Not rbtOk Then PE \"function as array\", Err.Number: Err.Clear\nEnd Sub\nFunction Dist(p As Point) As Double\n    Dist = Sqr(p.X ^ 2 + p.Y ^ 2)\nEnd Function\nFunction Bump()\n    Static n\n    n = n + 1\n    counter = counter + 1\n    Bump = n\nEnd Function\nFunction Opt(a, Optional b = 10)\n    Opt = a + b\nEnd Function\nFunction Missing(Optional v)\n    Missing = IsMissing(v)\nEnd Function\nFunction Total(ParamArray xs())\n    Dim x, t\n    For Each x In xs\n        t = t + x\n    Next\n    Total = t\nEnd Function\nFunction ByValTest()\n    Dim v\n    v = 1\n    Change v\n    ChangeVal v\n    ByValTest = v\nEnd Function\nSub Change(ByRef x)\n    x = x + 10\nEnd Sub\nSub ChangeVal(ByVal x)\n    x = x + 100\nEnd Sub\nFunction Fact(n)\n    If n <= 1 Then Fact = 1 Else Fact = n * Fact(n - 1)\nEnd Function\nFunction Squares()\n    Dim r(1 To 5), i\n    For i = 1 To 5: r(i) = i * i: Next\n    Squares = r\nEnd Function\n\nSub P(label, v)\n    rbtOk = True\n    rbtRow = rbtRow + 1\n    Worksheets(1).Cells(rbtRow, 1).Value = label\n    Worksheets(1).Cells(rbtRow, 3).Value = TypeName(v)\n    If IsObject(v) Or IsArray(v) Then Exit Sub\n    On Error Resume Next\n    Worksheets(1).Cells(rbtRow, 2).Value = v\n    If Err.Number <> 0 Then Worksheets(1).Cells(rbtRow, 2).Value = \"#cell \" & Err.Number: Err.Clear\n    Worksheets(1).Cells(rbtRow, 4).Value = \"'\" & CStr(v)\n    If Err.Number <> 0 Then Worksheets(1).Cells(rbtRow, 4).Value = \"#CStr \" & Err.Number\nEnd Sub\nSub PE(label, number)\n    rbtRow = rbtRow + 1\n    Worksheets(1).Cells(rbtRow, 1).Value = label\n    Worksheets(1).Cells(rbtRow, 2).Value = \"#ERR \" & number\nEnd Sub\n\n\nSub RbtParityMain()\n    On Error GoTo failed\n    Main\n    Exit Sub\nfailed:\n    Worksheets(1).Range(\"Z1\").Value = \"#ERR \" & Err.Number & \" \" & Err.Description\nEnd Sub\n"
    "control", "Private rbtRow As Long\nPrivate rbtOk As Boolean\nSub Main()\n    On Error Resume Next: rbtOk = False: P \"select is\", Classify(15): If Not rbtOk Then PE \"select is\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"select to\", Classify(5): If Not rbtOk Then PE \"select to\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"select list\", Classify(42): If Not rbtOk Then PE \"select list\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"select else\", Classify(-1): If Not rbtOk Then PE \"select else\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"select string\", Grade(\"b\"): If Not rbtOk Then PE \"select string\", Err.Number: Err.Clear\n    Dim i, n\n    Do While i < 5\n        i = i + 1\n    Loop\n    On Error Resume Next: rbtOk = False: P \"do while\", i: If Not rbtOk Then PE \"do while\", Err.Number: Err.Clear\n    i = 0\n    Do\n        i = i + 2\n    Loop Until i >= 7\n    On Error Resume Next: rbtOk = False: P \"loop until\", i: If Not rbtOk Then PE \"loop until\", Err.Number: Err.Clear\n    For i = 10 To 1 Step -3\n        n = n & i & \",\"\n    Next\n    On Error Resume Next: rbtOk = False: P \"for step\", n: If Not rbtOk Then PE \"for step\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"for after\", i: If Not rbtOk Then PE \"for after\", Err.Number: Err.Clear\n    For i = 1 To 10\n        If i = 4 Then Exit For\n    Next\n    On Error Resume Next: rbtOk = False: P \"exit for\", i: If Not rbtOk Then PE \"exit for\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"iif\", IIf(1 > 2, \"yes\", \"no\"): If Not rbtOk Then PE \"iif\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"choose\", Choose(2, \"a\", \"b\", \"c\"): If Not rbtOk Then PE \"choose\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"switch\", Switch(False, 1, True, 2): If Not rbtOk Then PE \"switch\", Err.Number: Err.Clear\n    Dim c As New Collection\n    c.Add \"first\"\n    c.Add \"second\", \"k2\"\n    c.Add \"zero\", Before:=1\n    On Error Resume Next: rbtOk = False: P \"collection count\", c.Count: If Not rbtOk Then PE \"collection count\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"collection item\", c(1) & \"|\" & c(\"k2\"): If Not rbtOk Then PE \"collection item\", Err.Number: Err.Clear\n    Dim t, item\n    For Each item In c\n        t = t & item & \";\"\n    Next\n    On Error Resume Next: rbtOk = False: P \"collection for each\", t: If Not rbtOk Then PE \"collection for each\", Err.Number: Err.Clear\n    c.Remove \"k2\"\n    On Error Resume Next: rbtOk = False: P \"collection remove\", c.Count: If Not rbtOk Then PE \"collection remove\", Err.Number: Err.Clear\n    On Error Resume Next\n    On Error Resume Next: rbtOk = False: P \"collection missing\", c(\"nope\"): If Not rbtOk Then PE \"collection missing\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"collection missing err\", Err.Number: If Not rbtOk Then PE \"collection missing err\", Err.Number: Err.Clear\n    Err.Clear\n    Dim d\n    Set d = CreateObject(\"Scripting.Dictionary\")\n    d(\"b\") = 2: d(\"a\") = 1\n    d.Add \"c\", 3\n    On Error Resume Next: rbtOk = False: P \"dict keys\", Join(d.Keys, \",\"): If Not rbtOk Then PE \"dict keys\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"dict exists\", d.Exists(\"a\"): If Not rbtOk Then PE \"dict exists\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"dict count\", d.Count: If Not rbtOk Then PE \"dict count\", Err.Number: Err.Clear\n    d.Add \"a\", 9\n    On Error Resume Next: rbtOk = False: P \"dict duplicate err\", Err.Number: If Not rbtOk Then PE \"dict duplicate err\", Err.Number: Err.Clear\n    Err.Clear\n    d.CompareMode = vbTextCompare\n    On Error Resume Next: rbtOk = False: P \"dict comparemode err\", Err.Number: If Not rbtOk Then PE \"dict comparemode err\", Err.Number: Err.Clear\n    Err.Clear\n    On Error Resume Next: rbtOk = False: P \"gosub\", ViaGoSub(): If Not rbtOk Then PE \"gosub\", Err.Number: Err.Clear\n    With Worksheets(1)\n        .Range(\"F1\").Value = \"with\"\n        With .Range(\"F2\")\n            .Value = \"inner\"\n        End With\n        .Range(\"F3\").Value = .Name\n    End With\nEnd Sub\nFunction Classify(x)\n    Select Case x\n        Case Is > 10: Classify = \"big\"\n        Case 1 To 9: Classify = \"small\"\n        Case 42, 43: Classify = \"answer\"\n        Case Else: Classify = \"other\"\n    End Select\nEnd Function\nFunction Grade(g)\n    Select Case UCase(g)\n        Case \"A\" To \"C\": Grade = \"good\"\n        Case Else: Grade = \"bad\"\n    End Select\nEnd Function\nFunction ViaGoSub()\n    Dim r\n    GoSub inner\n    ViaGoSub = r\n    Exit Function\ninner:\n    r = \"returned\"\n    Return\nEnd Function\n\nSub P(label, v)\n    rbtOk = True\n    rbtRow = rbtRow + 1\n    Worksheets(1).Cells(rbtRow, 1).Value = label\n    Worksheets(1).Cells(rbtRow, 3).Value = TypeName(v)\n    If IsObject(v) Or IsArray(v) Then Exit Sub\n    On Error Resume Next\n    Worksheets(1).Cells(rbtRow, 2).Value = v\n    If Err.Number <> 0 Then Worksheets(1).Cells(rbtRow, 2).Value = \"#cell \" & Err.Number: Err.Clear\n    Worksheets(1).Cells(rbtRow, 4).Value = \"'\" & CStr(v)\n    If Err.Number <> 0 Then Worksheets(1).Cells(rbtRow, 4).Value = \"#CStr \" & Err.Number\nEnd Sub\nSub PE(label, number)\n    rbtRow = rbtRow + 1\n    Worksheets(1).Cells(rbtRow, 1).Value = label\n    Worksheets(1).Cells(rbtRow, 2).Value = \"#ERR \" & number\nEnd Sub\n\n\nSub RbtParityMain()\n    On Error GoTo failed\n    Main\n    Exit Sub\nfailed:\n    Worksheets(1).Range(\"Z1\").Value = \"#ERR \" & Err.Number & \" \" & Err.Description\nEnd Sub\n"
    "dates", "Private rbtRow As Long\nPrivate rbtOk As Boolean\nSub Main()\n    Dim d As Date\n    d = DateSerial(2024, 1, 31)\n    On Error Resume Next: rbtOk = False: P \"dateserial\", d: If Not rbtOk Then PE \"dateserial\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"dateserial month 13\", DateSerial(2023, 13, 1): If Not rbtOk Then PE \"dateserial month 13\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"dateserial day 0\", DateSerial(2024, 3, 0): If Not rbtOk Then PE \"dateserial day 0\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"dateadd month end\", DateAdd(\"m\", 1, d): If Not rbtOk Then PE \"dateadd month end\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"dateadd days\", DateAdd(\"d\", 30, d): If Not rbtOk Then PE \"dateadd days\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"dateadd year leap\", DateAdd(\"yyyy\", 1, DateSerial(2024, 2, 29)): If Not rbtOk Then PE \"dateadd year leap\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"datediff days\", DateDiff(\"d\", DateSerial(2024, 1, 1), DateSerial(2024, 12, 31)): If Not rbtOk Then PE \"datediff days\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"datediff months\", DateDiff(\"m\", DateSerial(2024, 1, 31), DateSerial(2024, 2, 1)): If Not rbtOk Then PE \"datediff months\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"datediff weeks\", DateDiff(\"ww\", DateSerial(2024, 1, 1), DateSerial(2024, 3, 1)): If Not rbtOk Then PE \"datediff weeks\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"weekday\", Weekday(d): If Not rbtOk Then PE \"weekday\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"weekday monday\", Weekday(d, vbMonday): If Not rbtOk Then PE \"weekday monday\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"weekdayname\", WeekdayName(Weekday(d)): If Not rbtOk 