    "errors", "Private rbtRow As Long\nPrivate rbtOk As Boolean\nSub Main()\n    On Error Resume Next\n    Dim x, o As Object\n    x = 1 / 0: P \"div by zero\", Err.Number: P \"div text\", Err.Description: Err.Clear\n    x = \"a\" * 2: P \"type mismatch\", Err.Number: Err.Clear\n    Dim arr: arr = Array(1): x = arr(5): P \"subscript\", Err.Number: Err.Clear\n    x = o.Name: P \"object not set\", Err.Number: Err.Clear\n    x = CInt(99999): P \"overflow\", Err.Number: Err.Clear\n    x = Mid(\"abc\", 0): P \"invalid call\", Err.Number: Err.Clear\n    Err.Raise vbObjectError + 513, \"MySource\", \"custom\"\n    On Error Resume Next: rbtOk = False: P \"raise number\", Err.Number - vbObjectError: If Not rbtOk Then PE \"raise number\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"raise source\", Err.Source: If Not rbtOk Then PE \"raise source\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"raise description\", Err.Description: If Not rbtOk Then PE \"raise description\", Err.Number: Err.Clear\n    Err.Clear\n    On Error Resume Next: rbtOk = False: P \"cleared\", Err.Number: If Not rbtOk Then PE \"cleared\", Err.Number: Err.Clear\n    On Error GoTo 0\n    On Error Resume Next: rbtOk = False: P \"handler resume next\", Handled(): If Not rbtOk Then PE \"handler resume next\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"handler resume label\", Retried(): If Not rbtOk Then PE \"handler resume label\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"nested handler\", Outer(): If Not rbtOk Then PE \"nested handler\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"error in handler caller\", CallsFailing(): If Not rbtOk Then PE \"error in handler caller\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"typename err\", TypeName(Err): If Not rbtOk Then PE \"typename err\", Err.Number: Err.Clear\n    On Error Resume Next: rbtOk = False: P \"erl\", WithLines(): If Not rbtOk Then PE \"erl\", Err.Number: Err.Clear\nEnd Sub\nFunction Handled()\n    On Error GoTo h\n    Dim y\n    y = 1 / 0\n    Handled = \"after:\" & y\n    Exit Function\nh:\n    y = -1\n    Resume Next\nEnd Function\nFunction Retried()\n    Dim tries\n    On Error GoTo h\n    FailBelow tries, 3\n    Retried = \"tries:\" & tries\n    Exit Function\nh:\n    tries = tries + 1\n    Resume\nEnd Function\nSub FailBelow(n, limit)\n    If n < limit Then Err.Raise 5\nEnd Sub\nFunction Outer()\n    On Error GoTo h\n    Inner\n    Outer = \"no error\"\n    Exit Function\nh:\n    Outer = \"caught \" & Err.Number & \" from inner\"\nEnd Function\nSub Inner()\n    Err.Raise 1004, , \"deep\"\nEnd Sub\nFunction CallsFailing()\n    On Error Resume Next\n    Inner\n    CallsFailing = Err.Number & \" \" & Err.Description\nEnd Function\nFunction WithLines()\n    On Error GoTo h\n10  Dim a\n20  a = 1 / 0\n30  WithLines = \"none\"\n    Exit Function\nh:\n    WithLines = \"line \" & Erl\nEnd Function\n\nSub P(label, v)\n    rbtOk = True\n    rbtRow = rbtRow + 1\n    Worksheets(1).Cells(rbtRow, 1).Value = label\n    Worksheets(1).Cells(rbtRow, 3).Value = TypeName(v)\n    If IsObject(v) Or IsArray(v) Then Exit Sub\n    On Error Resume Next\n    Worksheets(1).Cells(rbtRow, 2).Value = v\n    If Err.Number <> 0 Then Worksheets(1).Cells(rbtRow, 2).Value = \"#cell \" & Err.Number: Err.Clear\n    Worksheets(1).Cells(rbtRow, 4).Value = \"'\" & CStr(v)\n    If Err.Number <> 0 Then Worksheets(1).Cells(rbtRow, 4).Value = \"#CStr \" & Err.Number\nEnd Sub\nSub PE(label, number)\n    rbtRow = rbtRow + 1\n    Worksheets(1).Cells(rbtRow, 1).Value = label\n    Worksheets(1).Cells(rbtRow, 2).Value = \"#ERR \" & number\nEnd Sub\n\n\nSub RbtParityMain()\n    On Error GoTo failed\n    Main\n    Exit Sub\nfailed:\n    Worksheets(1).Range(\"Z1\").Value = \"#ERR \" & Err.Number & \" \" & Err.Description\nEnd Sub\n"
